  "apps/docs/src/demos/field/react-hook-form.tsx": {
    "entry": "apps/docs/src/demos/field/react-hook-form.tsx",
    "files": [
      {
        "source": "apps/docs/src/demos/field/react-hook-form.tsx",
        "path": "examples/demos/field/react-hook-form.tsx",
        "content": "'use client';\n\nimport * as stylex from '@stylexjs/stylex';\nimport { Form } from '@base-ui/react/form';\nimport { space } from '@/lib/tokens.stylex';\nimport { Button } from '@/components/ui/button';\nimport { Field } from '@/components/ui/field';\nimport { Input } from '@/components/ui/input';\nimport { Controller, useForm } from 'react-hook-form';\n\nconst styles = stylex.create({\n  form: {\n    display: 'flex',\n    flexDirection: 'column',\n    gap: space['--ult-space-6'],\n    maxInlineSize: '24rem',\n  },\n});\n\ntype Values = {\n  handle: string;\n};\n\nexport default function ReactHookFormRecipe() {\n  const { control, handleSubmit, reset } = useForm<Values>({\n    defaultValues: { handle: '' },\n    shouldFocusError: true,\n  });\n\n  return (\n    <Form\n      {...stylex.props(styles.form)}\n      aria-label=\"Claim a handle\"\n      onSubmit={handleSubmit((values) => {\n        reset({ handle: values.handle });\n      })}\n    >\n      <Controller\n        name=\"handle\"\n        control={control}\n        rules={{\n          required: 'A handle is required.',\n          minLength: { value: 3, message: 'At least three characters.' },\n          validate: (value) => (value.toLowerCase() === 'admin' ? 'That handle is reserved.' : true),\n        }}\n        render={({ field: { ref, name, value, onBlur, onChange }, fieldState: { invalid, isTouched, isDirty, error } }) => (\n          <Field.Root name={name} invalid={invalid} touched={isTouched} dirty={isDirty}>\n            <Field.Label>Handle</Field.Label>\n            <Input\n              ref={ref}\n              value={value}\n              onBlur={onBlur}\n              onValueChange={onChange}\n              placeholder=\"frankie\"\n            />\n            <Field.Description>Reserved names are refused by the engine, not by a native attribute.</Field.Description>\n            <Field.Error match={!!error}>{error?.message}</Field.Error>\n          </Field.Root>\n        )}\n      />\n      <Button type=\"submit\">Claim handle</Button>\n    </Form>\n  );\n}\n"
      }
    ],
    "items": [
      "button",
      "field",
      "input",
      "tokens"
    ],
    "dependencies": [
      "@base-ui/react",
      "@stylexjs/stylex",
      "react-hook-form"
    ]
  },
  "apps/docs/src/demos/dialog/sheet.tsx": {
    "entry": "apps/docs/src/demos/dialog/sheet.tsx",
    "files": [
      {
        "source": "apps/docs/src/demos/dialog/sheet.tsx",
        "path": "examples/demos/dialog/sheet.tsx",
        "content": "import * as stylex from '@stylexjs/stylex';\nimport { border, motion, space } from '@/lib/tokens.stylex';\nimport { Button } from '@/components/ui/button';\nimport { Dialog } from '@/components/ui/dialog';\n\n/**\n * Dialog's own `transform` names a resting, a starting, and an ending state, and StyleX merges a\n * property one condition at a time, so each edge below names all three. An override that set only\n * the resting transform would leave Dialog's `scale(0.98)` alive underneath the slide.\n */\nconst sheet = stylex.create({\n  row: {\n    display: 'flex',\n    flexWrap: 'wrap',\n    gap: space['--ult-space-4'],\n  },\n  viewport: {\n    padding: 0,\n  },\n  popup: {\n    alignContent: 'start',\n    borderRadius: 0,\n    borderWidth: 0,\n    display: 'grid',\n    gap: space['--ult-space-4'],\n    justifyItems: 'start',\n    maxWidth: 'none',\n    transitionDuration: motion['--ult-motion-base'],\n    transitionProperty: 'opacity, transform',\n  },\n  leftViewport: {\n    placeItems: 'stretch start',\n  },\n  left: {\n    borderRightWidth: border.hairline,\n    width: `min(calc(5 * ${space['--ult-space-12']}), 100%)`,\n    transform: {\n      default: 'translateX(0)',\n      ':is([data-starting-style])': 'translateX(-100%)',\n      ':is([data-ending-style])': 'translateX(-100%)',\n    },\n  },\n  rightViewport: {\n    placeItems: 'stretch end',\n  },\n  right: {\n    borderLeftWidth: border.hairline,\n    width: `min(calc(5 * ${space['--ult-space-12']}), 100%)`,\n    transform: {\n      default: 'translateX(0)',\n      ':is([data-starting-style])': 'translateX(100%)',\n      ':is([data-ending-style])': 'translateX(100%)',\n    },\n  },\n  topViewport: {\n    placeItems: 'start stretch',\n  },\n  top: {\n    borderBottomWidth: border.hairline,\n    transform: {\n      default: 'translateY(0)',\n      ':is([data-starting-style])': 'translateY(-100%)',\n      ':is([data-ending-style])': 'translateY(-100%)',\n    },\n  },\n  bottomViewport: {\n    placeItems: 'end stretch',\n  },\n  bottom: {\n    borderTopWidth: border.hairline,\n    transform: {\n      default: 'translateY(0)',\n      ':is([data-starting-style])': 'translateY(100%)',\n      ':is([data-ending-style])': 'translateY(100%)',\n    },\n  },\n});\n\nconst EDGES = [\n  { edge: 'left', label: 'Left', viewport: sheet.leftViewport, popup: sheet.left },\n  { edge: 'right', label: 'Right', viewport: sheet.rightViewport, popup: sheet.right },\n  { edge: 'top', label: 'Top', viewport: sheet.topViewport, popup: sheet.top },\n  { edge: 'bottom', label: 'Bottom', viewport: sheet.bottomViewport, popup: sheet.bottom },\n] as const;\n\nexport default function SheetRecipe() {\n  return (\n    <div {...stylex.props(sheet.row)}>\n      {EDGES.map(({ edge, label, viewport, popup }) => (\n        <Dialog.Root key={edge}>\n          <Dialog.Trigger render={<Button variant=\"outline\" />}>{label}</Dialog.Trigger>\n          <Dialog.Portal>\n            <Dialog.Backdrop forceRender />\n            <Dialog.Viewport style={[sheet.viewport, viewport]}>\n              <Dialog.Popup style={[sheet.popup, popup]}>\n                <Dialog.Title>Filters</Dialog.Title>\n                <Dialog.Description>\n                  A Dialog anchored to the {edge} edge, sliding in from the side it sits on.\n                </Dialog.Description>\n                <Dialog.Close render={<Button variant=\"ghost\" />}>Close</Dialog.Close>\n              </Dialog.Popup>\n            </Dialog.Viewport>\n          </Dialog.Portal>\n        </Dialog.Root>\n      ))}\n    </div>\n  );\n}\n"
      }
    ],
    "items": [
      "button",
      "dialog",
      "tokens"
    ],
    "dependencies": [
      "@stylexjs/stylex"
    ]
  }
